plotFigControl(ALT_rd,ALT_st.name); %[output:180fc927] %[output:04c04514] %[output:6fc82176] %[output:6c7ddd92] %[output:4ac440da] %[output:9f6caed4] %[output:3f83ea28] %[output:2a37a975] %[output:6b425d10]
