lambdaSC=[450;550;700]*ones(1,4);lambdaAE=[467;530;660]*ones(1,4);lambdaAE7=[370 470 520 590 660 880 950]; %[output:7d571bcc] %[output:7741d487] %[output:515fbc1e] %[output:73bb5bab] %[output:0941e3f6] %[output:7ef29c58] %[output:13345d04] %[output:1f875358] %[output:0343a8eb] %[output:134f0999] %[output:9a2cbeed] %[output:5a37ae4e] %[output:14b419a2] %[output:2eed025e] %[output:63c7d654] %[output:3286971d] %[output:8adbc990] %[output:1d2cef02] %[output:64ffe42c] %[output:83e9bc3a] %[output:603c1ae6] %[output:6557c6f4] %[output:27c7266d] %[output:8a0cd08f] %[output:61a91e0b] %[output:7b05a143] %[output:0646845e] %[output:889c6ac2] %[output:50ae7865] %[output:31969c01] %[output:65ecff3f] %[output:6da0281f] %[output:4689faa8] %[output:586d21aa] %[output:10426892] %[output:8c2a3cc2] %[output:0aac60a0] %[output:08aec0c2] %[output:4afbb055] %[output:984a826c] %[output:482cfa5a] %[output:894f7c24] %[output:51be214f] %[output:05130fe2] %[output:2c5200ac] %[output:9c3b198b] %[output:99a3a02a] %[output:7ea299c4] %[output:8d203890] %[output:7d0d8eeb] %[output:62b035e7] %[output:65ce460d] %[output:9d15e641] %[output:187715aa] %[output:6d3514ca]
